        for (int vertex : vertices) {
            if (predicate.test(vertex)) {
                return true;
            }
        }
        return false;
    }

    public boolean allMatch(Predicate<Integer> predicate) {
        for (int vertex : vertices) {
            if (!predicate.test(vertex)) {
                return false;
            }
        }
        return true;
    }

