        return vertices.isEmpty() ? java.util.Optional.empty() : java.util.Optional.of(vertices.get(0));
    }

    public java.util.Optional<Integer> findAny() {
        return vertices.isEmpty() ? java.util.Optional.empty() : java.util.Optional.of(vertices.get(0));
    }

    public int sum() {
        int sum = 0;
        for (int vertex : vertices) {
            sum += vertex;
        }
        return sum;
