        return vertices.stream().mapToInt(Integer::intValue).max().orElse(Integer.MIN_VALUE);
    }

    public int min() {
        return vertices.stream().mapToInt(Integer::intValue).min().orElse(Integer.MAX_VALUE);
    }
}

